window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-513ba6d9affb6c72"]={"versions": [{"id": "FIG-513ba6d9affb6c72", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (M0-Instanzebene) im Kontext des AUTOSAR Generic Structure Template (TPS_GenericStructureTemplate). Das Diagramm veranschaulicht das Konzept wiederverwendbarer Typen und deren Instanziierungshierarchie anhand eines exemplarischen Fensterheber-Systems (PowerWindow).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind anonyme Instanzen (M0-Ebene, unterstrichene Bezeichner):</p>\n<ul class=\"fig-list\"><li><code>:PowerWindowType</code>: Übergeordnete Kompositum-Instanz an der Wurzel der Hierarchie.\n</li><li><code>:WindowControllerType</code>: Zwei separate Instanzen desselben Typs, aggregiert bzw. referenziert über die Rollen <code>+leftController</code> und <code>+rightController</code>.\n</li><li><code>:ControlInterface</code>: Zwei Schnittstellen-Instanzen desselben Typs, die jeweils einer Controller-Instanz über die Assoziationsrolle <code>+ctrl</code> zugeordnet sind.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Verhaltens- oder Sequenzspezifikation. Dargestellt ist eine statische Instanzkonstellation mit Rollenbeziehungen zur Verdeutlichung von Mehrfachinstanziierung wiederverwendbarer Komponenten- und Interface-Typen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Erläuterndes Instanzmodell für das Metamodellierungskonzept von AUTOSAR. Zeigt auf M0-Ebene, wie ein wiederverwendbarer Typ (<code>WindowControllerType</code>, <code>ControlInterface</code>) mehrfach in unterschiedlichen Rollenkontexten (<code>+leftController</code>, <code>+rightController</code>) innerhalb eines übergeordneten Typkontexts (<code>PowerWindowType</code>) instanziiert wird. Dient als formale Referenz für die Instanziierungssemantik von Typen und Prototypen bzw. Rollen im Generic Structure Template.</p>"}, {"id": "FIG-95154cc6c7e9208e", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (M0-Instanzebene) im Kontext des AUTOSAR Generic Structure Template (TPS_GenericStructureTemplate). Das Diagramm veranschaulicht das Konzept wiederverwendbarer Typen und deren Instanziierungshierarchie anhand eines exemplarischen Fensterheber-Systems (PowerWindow).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind anonyme Instanzen (M0-Ebene, unterstrichene Bezeichner):</p>\n<ul class=\"fig-list\"><li><code>:PowerWindowType</code>: Übergeordnete Kompositum-Instanz an der Wurzel der Hierarchie.\n</li><li><code>:WindowControllerType</code>: Zwei separate Instanzen desselben Typs, aggregiert bzw. referenziert über die Rollen <code>+leftController</code> und <code>+rightController</code>.\n</li><li><code>:ControlInterface</code>: Zwei Schnittstellen-Instanzen desselben Typs, die jeweils einer Controller-Instanz über die Assoziationsrolle <code>+ctrl</code> zugeordnet sind.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Verhaltens- oder Sequenzspezifikation. Dargestellt ist eine statische Instanzkonstellation mit Rollenbeziehungen zur Verdeutlichung von Mehrfachinstanziierung wiederverwendbarer Komponenten- und Interface-Typen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Erläuterndes Instanzmodell für das Metamodellierungskonzept von AUTOSAR. Zeigt auf M0-Ebene, wie ein wiederverwendbarer Typ (<code>WindowControllerType</code>, <code>ControlInterface</code>) mehrfach in unterschiedlichen Rollenkontexten (<code>+leftController</code>, <code>+rightController</code>) innerhalb eines übergeordneten Typkontexts (<code>PowerWindowType</code>) instanziiert wird. Dient als formale Referenz für die Instanziierungssemantik von Typen und Prototypen bzw. Rollen im Generic Structure Template.</p>"}, {"id": "FIG-b2682d3e4458bfb9", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (M0-Instanzebene) im Kontext des AUTOSAR Generic Structure Template (TPS_GenericStructureTemplate). Das Diagramm veranschaulicht das Konzept wiederverwendbarer Typen und deren Instanziierungshierarchie anhand eines exemplarischen Fensterheber-Systems (PowerWindow).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind anonyme Instanzen (M0-Ebene, unterstrichene Bezeichner):</p>\n<ul class=\"fig-list\"><li><code>:PowerWindowType</code>: Übergeordnete Kompositum-Instanz an der Wurzel der Hierarchie.\n</li><li><code>:WindowControllerType</code>: Zwei separate Instanzen desselben Typs, aggregiert bzw. referenziert über die Rollen <code>+leftController</code> und <code>+rightController</code>.\n</li><li><code>:ControlInterface</code>: Zwei Schnittstellen-Instanzen desselben Typs, die jeweils einer Controller-Instanz über die Assoziationsrolle <code>+ctrl</code> zugeordnet sind.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Verhaltens- oder Sequenzspezifikation. Dargestellt ist eine statische Instanzkonstellation mit Rollenbeziehungen zur Verdeutlichung von Mehrfachinstanziierung wiederverwendbarer Komponenten- und Interface-Typen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Erläuterndes Instanzmodell für das Metamodellierungskonzept von AUTOSAR. Zeigt auf M0-Ebene, wie ein wiederverwendbarer Typ (<code>WindowControllerType</code>, <code>ControlInterface</code>) mehrfach in unterschiedlichen Rollenkontexten (<code>+leftController</code>, <code>+rightController</code>) innerhalb eines übergeordneten Typkontexts (<code>PowerWindowType</code>) instanziiert wird. Dient als formale Referenz für die Instanziierungssemantik von Typen und Prototypen bzw. Rollen im Generic Structure Template.</p>"}, {"id": "FIG-874a087201cd565a", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (M0-Instanzebene) im Kontext des AUTOSAR Generic Structure Template (TPS_GenericStructureTemplate). Das Diagramm veranschaulicht das Konzept wiederverwendbarer Typen und deren Instanziierungshierarchie anhand eines exemplarischen Fensterheber-Systems (PowerWindow).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind anonyme Instanzen (M0-Ebene, unterstrichene Bezeichner):</p>\n<ul class=\"fig-list\"><li><code>:PowerWindowType</code>: Übergeordnete Kompositum-Instanz an der Wurzel der Hierarchie.\n</li><li><code>:WindowControllerType</code>: Zwei separate Instanzen desselben Typs, aggregiert bzw. referenziert über die Rollen <code>+leftController</code> und <code>+rightController</code>.\n</li><li><code>:ControlInterface</code>: Zwei Schnittstellen-Instanzen desselben Typs, die jeweils einer Controller-Instanz über die Assoziationsrolle <code>+ctrl</code> zugeordnet sind.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Verhaltens- oder Sequenzspezifikation. Dargestellt ist eine statische Instanzkonstellation mit Rollenbeziehungen zur Verdeutlichung von Mehrfachinstanziierung wiederverwendbarer Komponenten- und Interface-Typen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Erläuterndes Instanzmodell für das Metamodellierungskonzept von AUTOSAR. Zeigt auf M0-Ebene, wie ein wiederverwendbarer Typ (<code>WindowControllerType</code>, <code>ControlInterface</code>) mehrfach in unterschiedlichen Rollenkontexten (<code>+leftController</code>, <code>+rightController</code>) innerhalb eines übergeordneten Typkontexts (<code>PowerWindowType</code>) instanziiert wird. Dient als formale Referenz für die Instanziierungssemantik von Typen und Prototypen bzw. Rollen im Generic Structure Template.</p>"}], "trans": [{"from": "FIG-513ba6d9affb6c72", "to": "FIG-95154cc6c7e9208e", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-95154cc6c7e9208e", "to": "FIG-b2682d3e4458bfb9", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b2682d3e4458bfb9", "to": "FIG-874a087201cd565a", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
